import { useAuth } from "@/_core/hooks/useAuth";
import DashboardLayout from "@/components/DashboardLayout";
import PlatformAdminLayout from "@/components/PlatformAdminLayout";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { startLogin } from "@/const";
import { trpc } from "@/lib/trpc";
import { AdvancedDashboard, BranchFeaturePolicyPanel, ComplaintsPanel, GeneralPlatformSettingsPanel, GeneratorDirectorySearch, GeneratorInspector, InvoiceDeliverySettingsPanel, OperationalMonitoringPanel, OwnerLifecyclePanel, PasswordResetManagementPanel, OwnerManualLimitOverridesPanel, OwnerSubaccountLimitPolicyPanel, OwnerSubaccountPolicyPanel, OwnerSubscriberLimitPolicyPanel, OwnerUsagePriorityFiltersPanel, OwnerUsageQuickActionsPanel, OwnerUsageReportPanel, PlatformControlPanel, PlatformRolePoliciesPanel, SubscriptionUpgradeRequestsPanel } from "./AdminAdvancedWorkspace";
import OwnerSubscriptionRegistration from "./OwnerSubscriptionRegistration";
import GeneratorOperationsInspector from "./GeneratorOperationsInspector";
import ExcelJS from "exceljs";
import html2canvas from "html2canvas";
import jsPDF from "jspdf";
import { Building2, CalendarClock, CheckCircle2, CircleDollarSign, FileDown, FileSpreadsheet, FileText, Loader2, MessageSquareText, Plus, RefreshCw, ShieldAlert, UsersRound } from "lucide-react";
import { FormEvent, useEffect, useMemo, useRef, useState } from "react";
import { toast } from "sonner";

type Tab = "overview" | "generators" | "ownerSubscription" | "users" | "finance" | "reports" | "invoiceDelivery" | "tweetSms" | "smsPlans" | "complaints" | "notifications" | "security";
const inputClass = "h-10 w-full rounded-xl border border-white/10 bg-white/[0.025] px-3 text-sm text-white outline-none transition placeholder:text-slate-600 focus:border-[#F5B800]/70 focus:ring-2 focus:ring-[#F5B800]/15";
const formatNumber = (value: unknown) => new Intl.NumberFormat("ar").format(Number(value ?? 0));
const formatDate = (value: Date | string | null | undefined) => value ? new Date(value).toLocaleDateString("ar-IQ", { year: "numeric", month: "short", day: "numeric" }) : "—";
const paymentMethodLabels: Record<string, string> = { cash: "نقدي", wallet: "محفظة", bank_transfer: "تحويل بنكي", card: "بطاقة" };
const notificationStatusLabels: Record<string, string> = { pending: "بانتظار المعالجة", submitted: "مرسلة للمزود", delivered: "تم التسليم", read: "مقروءة", failed: "فاشلة" };

function statusLabel(status?: string) {
  return ({ trial: "تجريبي", active: "فعّال", overdue: "متأخر", suspended: "معلّق", cancelled: "ملغي" } as Record<string, string>)[status ?? ""] ?? "غير مهيأ";
}

function HideUnusedSubscriberOverview() {
  useEffect(() => { document.querySelector("h2")?.parentElement?.parentElement?.parentElement; const heading = Array.from(document.querySelectorAll("h2")).find((node) => node.textContent?.includes("مشتركو المنصة")); heading?.closest('[data-slot="card"]')?.remove(); }, []);
  return null;
}

export default function AdminConsolePage() {
  const { user, loading, isAuthenticated } = useAuth();
  const [tab, setTab] = useState<Tab>("overview");
  const [tenantFilter, setTenantFilter] = useState<number | undefined>();
  const isPlatformAdmin = user?.role === "admin";
  const utils = trpc.useUtils();
  const overview = trpc.admin.overview.useQuery(tenantFilter ? { tenantId: tenantFilter } : undefined, { enabled: isPlatformAdmin });
  const owners = trpc.admin.listOwners.useQuery(undefined, { enabled: isPlatformAdmin });
  const users = trpc.admin.userDirectory.useQuery(undefined, { enabled: isPlatformAdmin });
  const snapshot = trpc.admin.platformSnapshot.useQuery(undefined, { enabled: isPlatformAdmin });
  const notifications = trpc.admin.listNotifications.useQuery(undefined, { enabled: isPlatformAdmin });
  const security = trpc.admin.securityCenter.useQuery(undefined, { enabled: isPlatformAdmin });
  const smsPlans = trpc.admin.listSmsPlans.useQuery(undefined, { enabled: isPlatformAdmin });
  const smsRequests = trpc.admin.listSmsPackageRequests.useQuery(undefined, { enabled: isPlatformAdmin });
  const tweetSmsAccounts = trpc.admin.listTweetSmsAccounts.useQuery(undefined, { enabled: isPlatformAdmin });
  const refresh = async () => { await Promise.all([utils.admin.overview.invalidate(), utils.admin.listOwners.invalidate(), utils.admin.userDirectory.invalidate(), utils.admin.platformSnapshot.invalidate(), utils.admin.listNotifications.invalidate(), utils.admin.securityCenter.invalidate(), utils.admin.listSmsPlans.invalidate(), utils.admin.listSmsPackageRequests.invalidate(), utils.admin.listTweetSmsAccounts.invalidate(), utils.admin.getPlatformTweetSmsAccount.invalidate(), utils.admin.platformTweetSmsReport.invalidate()]); };
  const createOwnerSubscription = trpc.admin.createGeneratorOwnerSubscription.useMutation({ onSuccess: async () => { await refresh(); toast.success("تم إنشاء اشتراك صاحب المولد. يضيف المالك بيانات أول مولد بعد دخوله وتغيير كلمة المرور."); }, onError: (error) => toast.error(error.message) });
  const updateSubscription = trpc.admin.updateSubscription.useMutation({ onSuccess: async () => { await refresh(); toast.success("تم تحديث الاشتراك."); }, onError: (error) => toast.error(error.message) });
  const renewSubscription = trpc.admin.renewSubscription.useMutation({ onSuccess: async (result) => { await refresh(); toast.success(`تم التجديد حتى ${formatDate(result.endsAt)}.`); }, onError: (error) => toast.error(error.message) });
  const attachOwner = trpc.admin.attachOwnerUser.useMutation({ onSuccess: async () => { await refresh(); toast.success("تم ربط حساب المالك بالمساحة والمحطة."); }, onError: (error) => toast.error(error.message) });
  const reviewSmsRequest = trpc.admin.reviewSmsPackageRequest.useMutation({ onSuccess: async () => { await refresh(); toast.success("تمت مراجعة طلب الحزمة وتحديث حالته."); }, onError: (error) => toast.error(error.message) });
  const createSmsPlan = trpc.admin.createSmsPlan.useMutation({ onSuccess: async () => { await refresh(); toast.success("تم إنشاء باقة SMS."); }, onError: (error) => toast.error(error.message) });
  const updateSmsPlan = trpc.admin.updateSmsPlan.useMutation({ onSuccess: async () => { await refresh(); toast.success("تم تحديث باقة SMS."); }, onError: (error) => toast.error(error.message) });
  const overviewRows = overview.data?.owners ?? [];
  const reportRows = owners.data ?? [];
  const eligibleUsers = useMemo(() => (users.data ?? []).filter((candidate) => candidate.role !== "admin"), [users.data]);

  const downloadCsv = () => {
    const rows: Array<Array<string | number>> = [["صاحب المولد", "المساحة", "الحالة", "الخطة", "السكان", "التجاري", "الإجمالي", "ينتهي في"]];
    reportRows.forEach((row) => rows.push([row.owner?.fullName ?? "غير محدد", row.tenant.name, statusLabel(row.subscription?.status), row.subscription?.plan ?? row.tenant.plan, row.subscribers.residential, row.subscribers.commercial, row.subscribers.total, formatDate(row.subscription?.endsAt)]));
    const csv = "\uFEFF" + rows.map((row) => row.map((cell) => `"${String(cell ?? "").replaceAll('"', '""')}"`).join(",")).join("\n");
    const link = document.createElement("a");
    link.href = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" }));
    link.download = "powerhub-platform-admin-report.csv";
    link.click();
    URL.revokeObjectURL(link.href);
  };

  if (loading) return <DashboardLayout><div className="grid min-h-[60vh] place-items-center"><Loader2 className="h-8 w-8 animate-spin text-[#F5B800]" /></div></DashboardLayout>;
  if (!isAuthenticated) return <DashboardLayout><AccessCard title="سجّل الدخول إلى إدارة المنصة" action="تسجيل الدخول" onClick={startLogin} /></DashboardLayout>;
  if (!isPlatformAdmin) return <DashboardLayout><AccessCard title="هذه الصفحة مخصصة لآدمن PowerHub" detail="لا يمكن لصاحب مولد أو عضو فريق الوصول إلى بيانات جميع المستأجرين." /></DashboardLayout>;

  return <PlatformAdminLayout activeTab={tab} onTabChange={(nextTab) => setTab(nextTab as Tab)}><main className="space-y-6 pb-12"><header className="rounded-[26px] border border-[#F5B800]/20 bg-[#111823]/85 p-6 shadow-panel"><div className="flex flex-col justify-between gap-5 lg:flex-row lg:items-center"><div><div className="flex items-center gap-2 text-sm font-bold text-[#F5B800]"><ShieldAlert className="h-4 w-4" />إدارة PowerHub العليا</div><h1 className="mt-2 text-2xl font-extrabold text-white">مركز قيادة المنصة</h1><p className="mt-2 max-w-2xl text-sm leading-7 text-slate-400">إشراف مركزي منظم على المولدات والمشتركين والتحصيل والشكاوى وإعدادات الحماية عبر جميع مساحات PowerHub.</p></div><Button variant="outline" onClick={() => void refresh()} className="border-white/10 text-white hover:bg-white/5 hover:text-white"><RefreshCw className="ml-2 h-4 w-4" />تحديث البيانات</Button></div></header>
    {tab === "overview" && <><AdvancedDashboard /><OperationalMonitoringPanel onNavigate={(target) => target === "field_sync" ? window.location.assign("/field-sync") : setTab(target)} /><OwnerUsagePriorityFiltersPanel /><OwnerUsageQuickActionsPanel /><OwnerUsageReportPanel /></>}
    {tab === "generators" && <><GeneratorDirectorySearch rows={snapshot.data?.generators?.directory ?? []} /><GeneratorsCenter data={snapshot.data?.generators} /><GeneratorOperationsInspector rows={snapshot.data?.generators?.directory ?? []} /></>}
    {tab === "ownerSubscription" && <OwnerSubscriptionRegistration rows={owners.data ?? []} pending={createOwnerSubscription.isPending} onCreate={createOwnerSubscription.mutate} creationAvailable={true} />}
    {tab === "users" && <><HideUnusedSubscriberOverview /><UsersCenter userSummary={snapshot.data?.users} /><OwnerLifecyclePanel /><PasswordResetManagementPanel /></>}
    {tab === "finance" && <FinanceCenter data={snapshot.data?.finance} rows={owners.data ?? []} plans={smsPlans.data ?? []} pending={updateSubscription.isPending || renewSubscription.isPending} onUpdate={updateSubscription.mutate} onRenew={renewSubscription.mutate} />}
    {tab === "reports" && <><AdminReportsExports rows={reportRows} /><ReportsTab rows={reportRows} onDownload={downloadCsv} data={snapshot.data?.reports} generators={snapshot.data?.generators} /></>}
    {tab === "invoiceDelivery" && <InvoiceDeliverySettingsPanel />}
    {tab === "tweetSms" && <TweetSmsAccountsCenter accounts={tweetSmsAccounts.data ?? []} />}
    {tab === "smsPlans" && <SmsPlansCenter plans={smsPlans.data ?? []} requests={smsRequests.data ?? []} pending={reviewSmsRequest.isPending || createSmsPlan.isPending || updateSmsPlan.isPending} onReview={reviewSmsRequest.mutate} onCreatePlan={createSmsPlan.mutate} onUpdatePlan={updateSmsPlan.mutate} />}
    {tab === "complaints" && <ComplaintsPanel />}
    {tab === "notifications" && <NotificationsCenter data={snapshot.data?.notifications} rows={notifications.data ?? []} />}
    {tab === "security" && <SecurityCenter data={snapshot.data?.security} security={security.data} />}
  </main></PlatformAdminLayout>;
}

function SmsPlansCenter({ plans, requests, pending, onReview, onCreatePlan, onUpdatePlan }: any) {
  return <section className="space-y-6">
    <Card className="border-[#F5B800]/20 bg-[#111823] shadow-panel">
      <CardContent className="p-5">
        <div className="flex items-center gap-3"><MessageSquareText className="h-5 w-5 text-[#F5B800]" /><div><h2 className="font-bold text-white">إدارة باقات SMS</h2><p className="mt-1 text-sm text-slate-500">تعريف الباقات المركزية فقط. ربط الباقة بالاشتراك يتم من شاشة اشتراكات أصحاب المولدات، والاستهلاك يُحتسب تلقائيًا من الباقة والإضافيات المعتمدة.</p></div></div>
      </CardContent>
    </Card>

    <Card className="border-white/8 bg-[#111823] shadow-panel">
      <CardContent className="p-5">
        <h3 className="font-bold text-white">إنشاء باقة جديدة</h3>
        <form className="mt-4 grid gap-3 md:grid-cols-4" onSubmit={(event: FormEvent<HTMLFormElement>) => {
          event.preventDefault();
          const data = new FormData(event.currentTarget);
          onCreatePlan({
            code: String(data.get("code")).trim(),
            name: String(data.get("name")).trim(),
            description: String(data.get("description") || "").trim() || undefined,
            includedMessages: Number(data.get("includedMessages")),
            isActive: true,
          });
          event.currentTarget.reset();
        }}>
          <Input required name="code" placeholder="starter-sms" dir="ltr" className={inputClass} />
          <Input required name="name" placeholder="الباقة الأساسية" className={inputClass} />
          <Input required name="includedMessages" type="number" min="0" step="1" placeholder="عدد الرسائل الشهرية" dir="ltr" className={inputClass} />
          <div className="flex gap-2"><Input name="description" placeholder="وصف اختياري" className={inputClass} /><Button type="submit" disabled={pending} className="shrink-0 bg-[#F5B800] text-[#0D1117] hover:bg-[#ffd23f]">إنشاء</Button></div>
        </form>
      </CardContent>
    </Card>

    <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">
      {plans.map((plan: any) => <Card key={plan.id} className="border-white/8 bg-[#111823] shadow-panel">
        <CardContent className="p-5">
          <form className="space-y-3" onSubmit={(event: FormEvent<HTMLFormElement>) => {
            event.preventDefault();
            const data = new FormData(event.currentTarget);
            onUpdatePlan({
              id: plan.id,
              name: String(data.get("name")).trim(),
              description: String(data.get("description") || "").trim() || undefined,
              includedMessages: Number(data.get("includedMessages")),
              isActive: data.get("isActive") === "on",
            });
          }}>
            <div className="flex items-center justify-between gap-3"><span className="text-xs text-slate-500" dir="ltr">{plan.code}</span><label className="flex items-center gap-2 text-xs text-slate-400"><input name="isActive" type="checkbox" defaultChecked={plan.isActive} className="accent-[#F5B800]" />نشطة</label></div>
            <Input required name="name" defaultValue={plan.name} className={inputClass} />
            <Input required name="includedMessages" type="number" min="0" step="1" defaultValue={plan.includedMessages} dir="ltr" className={inputClass} />
            <Input name="description" defaultValue={plan.description ?? ""} className={inputClass} />
            <div className="flex items-center justify-between gap-3"><p className="text-xs text-slate-500">الحد الأساسي الشهري: {formatNumber(plan.includedMessages)}</p><Button type="submit" size="sm" disabled={pending} variant="outline" className="border-white/10 text-white hover:bg-white/5 hover:text-white">حفظ التعديل</Button></div>
          </form>
        </CardContent>
      </Card>)}
      {!plans.length && <Card className="border-white/8 bg-[#111823] md:col-span-2 xl:col-span-3"><CardContent className="p-8 text-center text-sm text-slate-500">لم تتم إضافة باقات SMS بعد.</CardContent></Card>}
    </div>

    <Card className="border-sky-400/15 bg-[#111823] shadow-panel">
      <CardContent className="p-0">
        <div className="border-b border-white/8 px-5 py-4"><h2 className="font-bold text-white">طلبات الحزم الإضافية</h2><p className="mt-1 text-sm text-slate-500">الاعتماد يضيف الرصيد إلى حصة الشهر الحالية للاشتراك، ولا يغيّر الباقة الأساسية.</p></div>
        <div className="overflow-x-auto"><table className="w-full min-w-[900px] text-right text-sm"><thead className="text-xs text-slate-500"><tr><th className="px-5 py-3">المالك</th><th className="px-4 py-3">المساحة</th><th className="px-4 py-3">المطلوب</th><th className="px-4 py-3">الحالة</th><th className="px-4 py-3">الإجراء</th></tr></thead>
          <tbody>{requests.map((row: any) => <tr key={row.request.id} className="border-t border-white/7"><td className="px-5 py-4 font-bold text-white">{row.ownerName ?? "—"}</td><td className="px-4 py-4 text-slate-300">{row.tenantName}</td><td className="px-4 py-4 text-[#F5B800]">{formatNumber(row.request.requestedMessages)}</td><td className="px-4 py-4 text-slate-400">{row.request.status === "pending" ? "قيد المراجعة" : row.request.status === "approved" ? `معتمد: ${formatNumber(row.request.approvedMessages)}` : row.request.status === "rejected" ? "مرفوض" : "ملغى"}</td><td className="px-4 py-4">{row.request.status === "pending" ? <div className="flex gap-2"><Button size="sm" disabled={pending} onClick={() => onReview({ id: row.request.id, status: "approved", approvedMessages: row.request.requestedMessages })} className="bg-emerald-400 text-[#0D1117] hover:bg-emerald-300">اعتماد وإضافة الرصيد</Button><Button size="sm" variant="outline" disabled={pending} onClick={() => onReview({ id: row.request.id, status: "rejected", approvedMessages: 0 })} className="border-rose-400/30 text-rose-300 hover:bg-rose-400/10 hover:text-rose-200">رفض</Button></div> : "—"}</td></tr>)}{!requests.length && <tr><td colSpan={5} className="px-5 py-10 text-center text-sm text-slate-500">لا توجد طلبات حزم إضافية.</td></tr>}</tbody>
        </table></div>
      </CardContent>
    </Card>
  </section>;
}
function TweetSmsAccountsCenter({ accounts }: any) {
  return <section className="space-y-6"><Card className="border-[#F5B800]/25 bg-[#111823] shadow-panel"><CardContent className="p-5"><div className="flex items-start gap-3"><MessageSquareText className="mt-0.5 h-5 w-5 text-[#F5B800]" /><div><h2 className="font-bold text-white">حسابات TweetSMS لأصحاب المولدات</h2><p className="mt-1 max-w-3xl text-sm leading-7 text-slate-400">عرض حالة الحسابات وحصص الرسائل فقط. إدارة المفاتيح وفحص المزود متوقفة في المسار القديم، لذلك لا تظهر أزرار تنفيذ غير قابلة للعمل.</p></div></div></CardContent></Card><div className="space-y-4">{accounts.map((account: any) => <Card key={account.tenantId} className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between"><div><p className="font-bold text-white">{account.ownerName ?? account.tenantName}</p><p className="mt-1 text-xs text-slate-500">{account.tenantName} · <span dir="ltr">{account.ownerPhone ?? "—"}</span></p></div><div className="flex flex-wrap gap-2"><Badge className={account.isActive ? "bg-emerald-400/10 text-emerald-300" : "bg-slate-400/10 text-slate-400"}>{account.isActive ? "الإرسال نشط" : "الإرسال موقوف"}</Badge><Badge className={account.configured ? "bg-sky-400/10 text-sky-300" : "bg-amber-400/10 text-amber-200"}>{account.configured ? "بيانات API محفوظة" : "بانتظار API"}</Badge></div></div><div className="mt-5 grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><div><p className="text-xs text-slate-500">اسم المرسل</p><p className="mt-1 font-bold text-white" dir="ltr">{account.senderName ?? "—"}</p></div><div><p className="text-xs text-slate-500">الحد الشهري</p><p className="mt-1 font-bold text-[#F5B800]">{formatNumber(account.monthlyLimit)} شريحة</p></div><div><p className="text-xs text-slate-500">المستخدم هذا الشهر</p><p className="mt-1 font-bold text-white">{formatNumber(account.usedThisMonth)} شريحة</p></div><div><p className="text-xs text-slate-500">المتبقي</p><p className="mt-1 font-bold text-emerald-300">{formatNumber(account.remaining)} شريحة</p></div></div>{account.lastError ? <p className="mt-4 rounded-xl border border-amber-400/20 bg-amber-400/[.05] px-3 py-2 text-xs leading-6 text-amber-200">آخر نتيجة: {account.lastError}</p> : null}</CardContent></Card>)}{!accounts.length && <Card className="border-white/8 bg-[#111823]"><CardContent className="p-10 text-center text-sm text-slate-500">لا توجد حسابات أصحاب مولدات مهيأة بعد.</CardContent></Card>}</div></section>;
}

function AccessCard({ title, detail, action, onClick }: { title: string; detail?: string; action?: string; onClick?: () => void }) { return <div className="mx-auto mt-14 max-w-xl rounded-[28px] border border-[#F5B800]/20 bg-[#111823] p-8 text-center shadow-panel"><ShieldAlert className="mx-auto h-9 w-9 text-[#F5B800]" /><h1 className="mt-5 text-xl font-extrabold text-white">{title}</h1><p className="mt-3 leading-7 text-slate-400">{detail ?? "يلزم وجود جلسة مصادق عليها للوصول إلى مساحة الإدارة."}</p>{action && <Button onClick={onClick} className="mt-6 bg-[#F5B800] font-bold text-[#0D1117] hover:bg-[#ffd23f]">{action}</Button>}</div>; }
function Metric({ label, value, icon: Icon }: { label: string; value: unknown; icon: typeof UsersRound }) { return <Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><Icon className="h-5 w-5 text-[#F5B800]" /><p className="mt-5 text-sm text-slate-400">{label}</p><p className="mt-2 font-display text-3xl font-extrabold text-white">{formatNumber(value)}</p></CardContent></Card>; }

function OverviewTab({ totals, rows, tenantFilter, onFilter, snapshot }: any) { return <section className="space-y-6"><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><Metric label="أصحاب المولدات" value={totals?.generatorOwners} icon={Building2} /><Metric label="مشتركو السكان" value={totals?.residential} icon={UsersRound} /><Metric label="المشتركون التجاريون" value={totals?.commercial} icon={CircleDollarSign} /><Metric label="إجمالي المشتركين" value={totals?.subscribers} icon={UsersRound} /><Metric label="اشتراكات فعّالة" value={totals?.activeSubscriptions} icon={CheckCircle2} /></div><div className="grid gap-4 md:grid-cols-3"><Metric label="المولدات العاملة" value={snapshot?.generators?.active} icon={Building2} /><Metric label="الفواتير المتأخرة" value={snapshot?.finance?.overdueCount} icon={CalendarClock} /><Metric label="رسائل تنتظر المعالجة" value={snapshot?.notifications?.statuses?.find((item: any) => item.status === "pending")?.count ?? 0} icon={CheckCircle2} /></div><Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><div className="mb-5 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><h2 className="font-bold text-white">المشتركون حسب صاحب المولد</h2><p className="mt-1 text-sm text-slate-500">اختر مساحة لعرض أعداد المشتركين المرتبطة بصاحب مولد معين.</p></div><select value={tenantFilter ?? ""} onChange={(event) => onFilter(event.target.value ? Number(event.target.value) : undefined)} className={inputClass + " sm:max-w-xs"}><option value="">كل أصحاب المولدات</option>{rows.map((row: any) => <option key={row.tenant.id} value={row.tenant.id}>{row.owner?.fullName ?? row.tenant.name}</option>)}</select></div><OwnerTable rows={rows} /></CardContent></Card></section>; }

function OwnerTable({ rows }: { rows: any[] }) { return <div className="overflow-x-auto"><table className="w-full min-w-[760px] text-right text-sm"><thead className="text-xs text-slate-500"><tr><th className="pb-3">صاحب المولد</th><th className="pb-3">المساحة</th><th className="pb-3">السكان</th><th className="pb-3">التجاري</th><th className="pb-3">الإجمالي</th><th className="pb-3">الاشتراك</th><th className="pb-3">ينتهي</th></tr></thead><tbody>{rows.map((row) => <tr className="border-t border-white/7" key={row.tenant.id}><td className="py-4 font-bold text-white">{row.owner?.fullName ?? "بانتظار ربط الحساب"}</td><td className="py-4 text-slate-300">{row.tenant.name}</td><td className="py-4">{formatNumber(row.subscribers.residential)}</td><td className="py-4">{formatNumber(row.subscribers.commercial)}</td><td className="py-4 font-bold text-[#F5B800]">{formatNumber(row.subscribers.total)}</td><td className="py-4"><Badge className="bg-white/5 text-slate-300">{statusLabel(row.subscription?.status)}</Badge></td><td className="py-4 text-slate-400">{formatDate(row.subscription?.endsAt)}</td></tr>)}{!rows.length && <tr><td colSpan={7} className="py-10 text-center text-slate-500">لا توجد مساحات أصحاب مولدات مسجلة بعد.</td></tr>}</tbody></table></div>; }

function OwnersTab({ users, rows, pending, onCreate, onAttach }: any) { return <section className="grid gap-6 xl:grid-cols-[.9fr_1.1fr]"><Card className="border-[#F5B800]/20 bg-[#111823] shadow-panel"><CardContent className="p-5"><h2 className="font-bold text-white">إضافة صاحب مولد جديد</h2><p className="mt-1 text-sm leading-6 text-slate-500">ينشئ حساب Supabase ومحطة ومولداً فعلياً بحالة انتظار المراجعة. لا تُخزن كلمة المرور في PowerHub، ويُلزم المالك بتغييرها عند أول دخول.</p><form className="mt-6 space-y-4" onSubmit={(event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); onCreate({ tenantName: String(data.get("tenantName")), slug: String(data.get("slug")).toLowerCase(), ownerName: String(data.get("ownerName")), ownerPhone: String(data.get("ownerPhone")), ownerEmail: String(data.get("ownerEmail")), identityNumber: String(data.get("identityNumber")), generatorName: String(data.get("generatorName")), generatorCode: String(data.get("generatorCode")), generatorCapacityKw: Number(data.get("generatorCapacityKw")), generatorFuelType: String(data.get("generatorFuelType")), companyName: String(data.get("companyName") || "") || undefined, temporaryPassword: String(data.get("temporaryPassword")), siteName: String(data.get("siteName")), siteCode: String(data.get("siteCode")), city: String(data.get("city") || "") || undefined, plan: String(data.get("plan")), subscriptionStatus: String(data.get("subscriptionStatus")), billingCycle: String(data.get("billingCycle")), endsAt: data.get("endsAt") ? new Date(`${String(data.get("endsAt"))}T23:59:59`) : undefined, autoRenew: data.get("autoRenew") === "on", notes: String(data.get("notes") || "") || undefined }); }}><Input required name="tenantName" placeholder="اسم مساحة صاحب المولد" className={inputClass} /><Input required name="slug" placeholder="owner-space-slug" dir="ltr" className={inputClass} /><Input required name="ownerName" placeholder="الاسم الكامل لصاحب المولد" className={inputClass} /><div className="grid gap-3 sm:grid-cols-2"><Input required name="ownerPhone" placeholder="رقم الهاتف الفريد" dir="ltr" className={inputClass} /><Input required name="ownerEmail" type="email" placeholder="البريد الإلكتروني الفريد" dir="ltr" className={inputClass} /></div><div className="grid gap-3 sm:grid-cols-2"><Input required name="identityNumber" placeholder="رقم الهوية" dir="ltr" className={inputClass} /><Input required name="temporaryPassword" type="password" minLength={8} placeholder="كلمة مرور مؤقتة (8+ رموز)" dir="ltr" className={inputClass} /></div><Input name="companyName" placeholder="اسم الشركة أو النشاط" className={inputClass} /><div className="grid gap-3 sm:grid-cols-2"><Input required name="siteName" placeholder="اسم المحطة الأولى" className={inputClass} /><Input required name="siteCode" placeholder="PH-OWNER-01" dir="ltr" className={inputClass} /></div><div className="grid gap-3 sm:grid-cols-2"><Input required name="generatorName" placeholder="اسم المولد الفريد" className={inputClass} /><Input required name="generatorCode" placeholder="GEN-OWNER-01" dir="ltr" className={inputClass} /></div><div className="grid gap-3 sm:grid-cols-2"><Input required name="generatorCapacityKw" type="number" min="0.001" step="0.001" placeholder="قدرة المولد kW" dir="ltr" className={inputClass} /><select required name="generatorFuelType" className={inputClass}><option value="diesel">ديزل</option><option value="gasoline">بنزين</option><option value="gas">غاز</option><option value="other">أخرى</option></select></div><Input name="city" placeholder="المدينة" className={inputClass} /><div className="grid gap-3 sm:grid-cols-2"><select name="plan" className={inputClass}><option value="starter">Starter</option><option value="professional">Professional</option><option value="enterprise">Enterprise</option></select><select name="subscriptionStatus" className={inputClass}><option value="trial">تجريبي</option><option value="active">فعّال</option><option value="suspended">معلّق</option></select></div><div className="grid gap-3 sm:grid-cols-2"><select name="billingCycle" className={inputClass}><option value="monthly">شهري</option><option value="yearly">سنوي</option></select><Input name="endsAt" type="date" className={inputClass} /></div><label className="flex items-center gap-2 text-sm text-slate-400"><input name="autoRenew" type="checkbox" className="accent-[#F5B800]" />تجديد تلقائي</label><textarea name="notes" className="min-h-20 w-full rounded-xl border border-white/10 bg-white/[0.025] p-3 text-sm text-white outline-none focus:border-[#F5B800]/70" placeholder="ملاحظات الاشتراك" /><Button disabled={pending} className="w-full bg-[#F5B800] font-bold text-[#0D1117] hover:bg-[#ffd23f]"><Plus className="ml-2 h-4 w-4" />إنشاء صاحب المولد والمولد المعلّق</Button></form></CardContent></Card><Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><h2 className="font-bold text-white">أصحاب المولدات المسجلون</h2><div className="mt-4 space-y-3">{rows.map((row: any) => <div className="rounded-xl border border-white/8 bg-white/[0.02] p-4" key={row.tenant.id}><div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-bold text-white">{row.owner?.fullName ?? "صاحب مولد غير مربوط بحساب"}</p><p className="mt-1 text-xs text-slate-500">{row.tenant.name} · {row.owner?.phone ?? "لا يوجد هاتف"}</p></div><Badge className="w-fit bg-[#F5B800]/10 text-[#F5B800]">{row.tenant.plan}</Badge></div>{!row.owner?.ownerUserId && <div className="mt-4 flex flex-col gap-2 sm:flex-row"><select className={inputClass} defaultValue="" aria-label={`حساب مالك ${row.tenant.name}`}><option value="">اختر حساباً للربط</option>{users.map((candidate: any) => <option key={candidate.id} value={candidate.id}>{candidate.name ?? candidate.email ?? `مستخدم #${candidate.id}`}</option>)}</select><Button variant="outline" className="border-white/10 text-white hover:bg-white/5 hover:text-white" onClick={(event) => { const select = (event.currentTarget.parentElement?.querySelector("select") as HTMLSelectElement | null); if (!select?.value) return toast.error("اختر حساب المستخدم أولاً."); onAttach({ tenantId: row.tenant.id, userId: Number(select.value) }); }}>ربط الحساب</Button></div>}</div>)}{!rows.length && <p className="py-10 text-center text-sm text-slate-500">لم يُضف أي صاحب مولد بعد.</p>}</div></CardContent></Card></section>; }

function SubscriptionsTab({ rows, pending, onUpdate, onRenew, smsPlans = [] }: any) { return <section className="space-y-4">{rows.map((row: any) => <Card className="border-white/8 bg-[#111823] shadow-panel" key={row.tenant.id}><CardContent className="p-5"><div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between"><div><p className="font-bold text-white">{row.owner?.fullName ?? row.tenant.name}</p><p className="mt-1 text-sm text-slate-500">{row.tenant.name} · انتهاء الاشتراك: {formatDate(row.subscription?.endsAt)}</p></div><div className="flex gap-2"><Button disabled={pending} onClick={() => onRenew({ tenantId: row.tenant.id, periods: 1 })} className="bg-[#F5B800] text-[#0D1117] hover:bg-[#ffd23f]"><RefreshCw className="ml-2 h-4 w-4" />تجديد دورة</Button></div></div><form className="mt-5 grid gap-3 md:grid-cols-5" onSubmit={(event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); onUpdate({ tenantId: row.tenant.id, plan: String(data.get("plan")), status: String(data.get("status")), billingCycle: String(data.get("billingCycle")), endsAt: new Date(`${String(data.get("endsAt"))}T23:59:59`), autoRenew: data.get("autoRenew") === "on", notes: String(data.get("notes") || "") || undefined, smsPlanId: data.get("smsPlanId") ? Number(data.get("smsPlanId")) : null }); }}><select name="plan" defaultValue={row.subscription?.plan ?? row.tenant.plan} className={inputClass}><option value="starter">Starter</option><option value="professional">Professional</option><option value="enterprise">Enterprise</option></select><select name="smsPlanId" defaultValue={row.subscription?.smsPlanId ?? ""} className={inputClass}><option value="">بدون خطة SMS مخصصة</option>{smsPlans.filter((plan: any) => plan.isActive).map((plan: any) => <option key={plan.id} value={plan.id}>{plan.name} · {formatNumber(plan.includedMessages)} رسالة</option>)}</select><select name="status" defaultValue={row.subscription?.status ?? "trial"} className={inputClass}><option value="trial">تجريبي</option><option value="active">فعّال</option><option value="overdue">متأخر</option><option value="suspended">معلّق</option><option value="cancelled">ملغي</option></select><select name="billingCycle" defaultValue={row.subscription?.billingCycle ?? "monthly"} className={inputClass}><option value="monthly">شهري</option><option value="yearly">سنوي</option></select><Input required name="endsAt" type="date" defaultValue={row.subscription?.endsAt ? new Date(row.subscription.endsAt).toISOString().slice(0, 10) : ""} className={inputClass} /><label className="flex items-center gap-2 text-sm text-slate-400"><input defaultChecked={row.subscription?.autoRenew} name="autoRenew" type="checkbox" className="accent-[#F5B800]" />تجديد تلقائي</label><textarea name="notes" defaultValue={row.subscription?.notes ?? ""} placeholder="ملاحظات" className="min-h-10 rounded-xl border border-white/10 bg-white/[0.025] p-2 text-sm text-white outline-none md:col-span-4" /><Button disabled={pending} className="bg-white/8 text-white hover:bg-white/12">حفظ الاشتراك</Button></form></CardContent></Card>)}{!rows.length && <Card className="border-white/8 bg-[#111823]"><CardContent className="p-10 text-center text-slate-500">لا توجد اشتراكات مسجلة حتى الآن.</CardContent></Card>}</section>; }

function AdminReportsExports({ rows }: { rows: any[] }) {
  const pdfRef = useRef<HTMLDivElement>(null);
  const fileRows = rows.map((row) => [row.owner?.fullName ?? "غير محدد", row.tenant.name, statusLabel(row.subscription?.status), row.subscription?.plan ?? row.tenant.plan, row.subscribers.residential, row.subscribers.commercial, row.subscribers.total, formatDate(row.subscription?.endsAt)]);
  const exportExcel = async () => { const workbook = new ExcelJS.Workbook(); workbook.creator = "PowerHub"; const sheet = workbook.addWorksheet("تقرير الإدارة", { views: [{ rightToLeft: true }] }); sheet.addRow(["تقرير إدارة PowerHub"]); sheet.addRow(["تاريخ الإصدار", new Date().toLocaleDateString("ar-IQ")]); sheet.addRow([]); sheet.addRow(["صاحب المولد", "المساحة", "الحالة", "الخطة", "السكان", "التجاري", "الإجمالي", "ينتهي في"]); fileRows.forEach((row) => sheet.addRow(row)); sheet.columns = [{ width: 28 }, { width: 26 }, { width: 16 }, { width: 16 }, { width: 14 }, { width: 14 }, { width: 14 }, { width: 18 }]; [1, 4].forEach((index) => { const row = sheet.getRow(index); row.font = { bold: true, color: { argb: "FFFFFFFF" } }; row.fill = { type: "pattern", pattern: "solid", fgColor: { argb: "FF0D1117" } }; }); const blob = new Blob([await workbook.xlsx.writeBuffer()], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" }); const link = document.createElement("a"); link.href = URL.createObjectURL(blob); link.download = "powerhub-platform-admin-report.xlsx"; link.click(); URL.revokeObjectURL(link.href); toast.success("تم تجهيز تقرير الإدارة بصيغة Excel."); };
  const exportPdf = async () => { if (!pdfRef.current) return; try { const canvas = await html2canvas(pdfRef.current, { scale: 2, backgroundColor: "#ffffff" }); const pdf = new jsPDF("p", "pt", "a4"); const width = pdf.internal.pageSize.getWidth(); const height = canvas.height * width / canvas.width; let offset = 0; const pageHeight = pdf.internal.pageSize.getHeight(); while (offset < height) { pdf.addImage(canvas.toDataURL("image/png"), "PNG", 0, -offset, width, height); offset += pageHeight; if (offset < height) pdf.addPage(); } pdf.save("powerhub-platform-admin-report.pdf"); toast.success("تم تجهيز تقرير الإدارة بصيغة PDF."); } catch { toast.error("تعذر إنشاء PDF لتقرير الإدارة. حاول مرة أخرى."); } };
  return <><Card className="border-[#F5B800]/20 bg-[#F5B800]/[.035] shadow-panel"><CardContent className="flex flex-col gap-3 p-5 lg:flex-row lg:items-center lg:justify-between"><div><h2 className="font-bold text-white">تصدير تقرير الإدارة العليا</h2><p className="mt-1 text-sm leading-6 text-slate-400">ملف رسمي يضم أصحاب المولدات والاشتراكات وأعداد المشتركين في المنصة.</p></div><div className="flex flex-wrap gap-2"><Button onClick={exportExcel} className="bg-[#F5B800] text-[#0D1117] hover:bg-[#ffd23f]"><FileSpreadsheet className="ml-2 h-4 w-4" />Excel</Button><Button onClick={exportPdf} variant="outline" className="border-[#F5B800]/40 text-[#F5B800] hover:bg-[#F5B800]/10 hover:text-[#ffd23f]"><FileText className="ml-2 h-4 w-4" />PDF</Button></div></CardContent></Card><div ref={pdfRef} className="pointer-events-none fixed left-[-9999px] top-0 w-[760px] bg-white p-10 text-right text-[#0D1117]" dir="rtl"><header className="border-b-4 border-[#F5B800] pb-5"><p className="text-sm font-bold text-[#A17400]">POWERHUB — إدارة الطاقة بذكاء</p><h1 className="mt-2 text-3xl font-extrabold">تقرير إدارة المنصة</h1><p className="mt-2 text-sm">تاريخ الإصدار: {new Date().toLocaleDateString("ar-IQ")}</p></header><table className="mt-7 w-full border-collapse text-sm"><thead><tr>{["صاحب المولد", "المساحة", "الحالة", "الخطة", "المشتركون", "ينتهي في"].map((title) => <th className="border border-[#D9DEE5] bg-[#F5F6F8] p-2" key={title}>{title}</th>)}</tr></thead><tbody>{fileRows.map((row, index) => <tr key={index}><td className="border border-[#D9DEE5] p-2">{row[0]}</td><td className="border border-[#D9DEE5] p-2">{row[1]}</td><td className="border border-[#D9DEE5] p-2">{row[2]}</td><td className="border border-[#D9DEE5] p-2">{row[3]}</td><td className="border border-[#D9DEE5] p-2">{row[6]}</td><td className="border border-[#D9DEE5] p-2">{row[7]}</td></tr>)}</tbody></table><p className="mt-7 text-center text-xs text-[#647080]">هذا التقرير صادر إلكترونياً من PowerHub.</p></div></>;
}

function ReportsTab({ rows, onDownload, data, generators }: { rows: any[]; onDownload: () => void; data: any; generators: any }) { const totals = rows.reduce((acc, row) => ({ owners: acc.owners + 1, subscribers: acc.subscribers + row.subscribers.total, endingSoon: acc.endingSoon + (row.subscription?.endsAt && new Date(row.subscription.endsAt) < new Date(Date.now() + 30 * 86400000) ? 1 : 0) }), { owners: 0, subscribers: 0, endingSoon: 0 }); return <section className="space-y-6"><div className="grid gap-4 md:grid-cols-3"><Metric label="إجمالي المساحات" value={totals.owners} icon={Building2} /><Metric label="إجمالي المشتركين" value={totals.subscribers} icon={UsersRound} /><Metric label="تنتهي خلال 30 يوماً" value={totals.endingSoon} icon={CalendarClock} /></div><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4"><ReportCard title="أداء المولدات" value={`${formatNumber(generators?.active)} / ${formatNumber(generators?.total)}`} detail="مولدات عاملة من إجمالي المولدات" /><ReportCard title="الاستهلاك العام" value={`${formatNumber(data?.consumptionKwh)} kWh`} detail={`${formatNumber(data?.approvedReadings)} قراءة معتمدة`} /><ReportCard title="تقرير النمو" value={formatNumber(data?.subscribers)} detail={`${formatNumber(data?.tenants)} مساحة نشطة أو مهيأة في المنصة`} /><ReportCard title="تقرير الشكاوى" value="غير مفعّل" detail="لا توجد وحدة شكاوى مرتبطة بالبيانات حتى الآن" /></div><Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><h2 className="font-bold text-white">تقرير المنصة</h2><p className="mt-1 text-sm text-slate-500">ملخص قابل للتصدير لأصحاب المولدات والاشتراكات وأعداد المشتركين.</p></div><Button onClick={onDownload} className="bg-[#F5B800] text-[#0D1117] hover:bg-[#ffd23f]"><FileDown className="ml-2 h-4 w-4" />تصدير CSV</Button></div><div className="mt-5"><OwnerTable rows={rows} /></div></CardContent></Card></section>; }
function ReportCard({ title, value, detail }: { title: string; value: string; detail: string }) { return <Card className="border-white/8 bg-[#111823]"><CardContent className="p-5"><p className="text-sm text-slate-400">{title}</p><p className="mt-3 text-xl font-extrabold text-white">{value}</p><p className="mt-2 text-xs leading-6 text-slate-500">{detail}</p></CardContent></Card>; }

function GeneratorsCenter({ data }: any) {
  const rows = data?.directory ?? [];
  const label = (status: string) => status === "pending" ? "بانتظار المراجعة" : status === "active" ? "يعمل" : status === "maintenance" ? "صيانة" : status === "offline" ? "غير متصل" : status === "blocked" ? "محظور" : "متوقف";
  return <section className="space-y-6">
    <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-6">
      <Metric label="جميع المولدات" value={data?.total} icon={Building2} />
      <Metric label="بانتظار المراجعة" value={data?.pending} icon={CalendarClock} />
      <Metric label="المولدات العاملة" value={data?.active} icon={CheckCircle2} />
      <Metric label="قيد الصيانة" value={data?.maintenance} icon={CalendarClock} />
      <Metric label="موقوفة أو غير متصلة" value={data?.stopped} icon={ShieldAlert} />
      <Metric label="مولدات محظورة" value={data?.blocked} icon={ShieldAlert} />
    </div>
    <div className="grid gap-6 xl:grid-cols-[1.35fr_.65fr]">
      <Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5">
        <h2 className="font-bold text-white">جميع المولدات</h2>
        <p className="mt-1 text-sm text-slate-500">عرض تشغيلي للقراءة فقط؛ تغييرات الحالة تتم عبر المسار الإداري المعتمد.</p>
        <div className="mt-5 overflow-x-auto"><table className="w-full min-w-[720px] text-right text-sm">
          <thead className="text-xs text-slate-500"><tr><th className="pb-3">المولد</th><th className="pb-3">المالك / المحطة</th><th className="pb-3">القدرة</th><th className="pb-3">الحالة</th></tr></thead>
          <tbody>{rows.map((row: any) => <tr key={row.id} className="border-t border-white/7"><td className="py-4 font-bold text-white">{row.name}<span className="mr-2 text-xs font-normal text-slate-500">{row.code}</span></td><td className="py-4 text-slate-300">{row.tenantName} · {row.siteName}</td><td className="py-4">{row.ratedCapacityKw} kW</td><td className="py-4"><Badge className={row.status === "pending" ? "bg-amber-400/10 text-amber-300" : row.status === "blocked" ? "bg-rose-400/10 text-rose-300" : "bg-white/5 text-slate-300"}>{label(row.status)}</Badge></td></tr>)}{!rows.length && <tr><td colSpan={4} className="py-10 text-center text-slate-500">لا توجد مولدات مسجلة بعد.</td></tr>}</tbody>
        </table></div>
      </CardContent></Card>
      <Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><h2 className="font-bold text-white">طلبات المراجعة المعلقة</h2><p className="mt-1 text-sm text-slate-500">تظهر هنا للمتابعة فقط؛ لا يوجد إجراء تفعيل قابل للتنفيذ في هذه الشاشة.</p><div className="mt-5 space-y-3">{(data?.pendingRegistrations ?? []).map((row: any) => <div className="rounded-xl border border-amber-400/15 bg-amber-400/[.03] p-3" key={row.generatorId}><p className="font-bold text-white">{row.generatorName}</p><p className="mt-1 text-xs text-slate-500">{row.generatorCode} · {row.ratedCapacityKw} kW</p><p className="mt-1 text-xs text-slate-500">{row.ownerName} · {row.phone}</p><Badge className="mt-3 bg-amber-400/10 text-amber-200">بانتظار الإجراء الإداري</Badge></div>)}{!(data?.pendingRegistrations ?? []).length && <p className="py-6 text-center text-sm text-slate-500">لا توجد طلبات معلقة.</p>}</div></CardContent></Card>
    </div>
  </section>;
}

function UsersCenter({ userSummary }: any) { const staff = userSummary?.staffDirectory ?? []; const subscriberRows = userSummary?.subscriberDirectory ?? []; const roleLabels: Record<string, string> = { owner: "مالك", manager: "مدير", accountant: "محاسب", collector: "محصل", technician: "فني", viewer: "مشاهد" }; return <section className="space-y-6"><div className="grid gap-4 md:grid-cols-3"><Metric label="مستخدمو المنصة" value={userSummary?.total} icon={UsersRound} /><Metric label="موظفون نشطون" value={userSummary?.activeStaff} icon={UsersRound} /><Metric label="آدمن المنصة" value={userSummary?.platformAdmins} icon={ShieldAlert} /></div><div className="grid gap-6 xl:grid-cols-2"><Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><h2 className="font-bold text-white">المحاسبون والموظفون</h2><p className="mt-1 text-sm text-slate-500">قائمة مركزية للموظفين المرتبطين بمحطات أصحاب المولدات.</p><div className="mt-4 max-h-80 overflow-auto"><table className="w-full min-w-[520px] text-right text-sm"><thead className="text-xs text-slate-500"><tr><th className="pb-3">المستخدم</th><th className="pb-3">الدور</th><th className="pb-3">المساحة / المحطة</th><th className="pb-3">الحالة</th></tr></thead><tbody>{staff.map((row: any) => <tr className="border-t border-white/7" key={row.id}><td className="py-3 text-white">{row.userName ?? row.userEmail ?? "—"}</td><td className="py-3"><Badge className="bg-white/5 text-slate-300">{roleLabels[row.role] ?? row.role}</Badge></td><td className="py-3 text-slate-400">{row.tenantName ?? "—"} · {row.siteName ?? "—"}</td><td className="py-3 text-slate-400">{row.isActive ? "نشط" : "موقوف"}</td></tr>)}{!staff.length && <tr><td colSpan={4} className="py-8 text-center text-slate-500">لا يوجد موظفون مسجلون بعد.</td></tr>}</tbody></table></div></CardContent></Card><Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><h2 className="font-bold text-white">مشتركو المنصة — عرض عام</h2><p className="mt-1 text-sm text-slate-500">عرض مراقبة مركزي للبيانات الأساسية دون صلاحية تعديل الاشتراك.</p><div className="mt-4 max-h-80 overflow-auto"><table className="w-full min-w-[540px] text-right text-sm"><thead className="text-xs text-slate-500"><tr><th className="pb-3">المشترك</th><th className="pb-3">النوع</th><th className="pb-3">الحالة</th><th className="pb-3">المساحة / المحطة</th></tr></thead><tbody>{subscriberRows.map((row: any) => <tr className="border-t border-white/7" key={row.id}><td className="py-3 text-white">{row.fullName}<span className="mr-2 text-xs text-slate-500">{row.subscriberNo}</span></td><td className="py-3 text-slate-400">{row.subscriptionType === "commercial" ? "تجاري" : "سكني"}</td><td className="py-3 text-slate-400">{row.serviceStatus === "active" ? "نشط" : row.serviceStatus}</td><td className="py-3 text-slate-400">{row.tenantName} · {row.siteName}</td></tr>)}{!subscriberRows.length && <tr><td colSpan={4} className="py-8 text-center text-slate-500">لا يوجد مشتركون مسجلون بعد.</td></tr>}</tbody></table></div></CardContent></Card></div><Card className="border-white/8 bg-[#111823]"><CardContent className="p-5"><h2 className="font-bold text-white">مصفوفة صلاحيات الأدوار</h2><div className="mt-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-3"><RolePolicy role="آدمن PowerHub" detail="إدارة المنصة والمساحات والاشتراكات والتقارير العامة." /><RolePolicy role="مالك المولد" detail="إدارة مستأجره ومحطاته وفريقه فقط." /><RolePolicy role="المدير / المحاسب" detail="تشغيل وفوترة وتحكم مالي حسب تعيين المحطة." /><RolePolicy role="المحصل" detail="تحصيل ضمن جلسة ميدانية مفتوحة." /><RolePolicy role="الفني" detail="العدادات والقراءات والمولدات حسب التعيين." /><RolePolicy role="المشاهد" detail="عرض البيانات المصرح بها بلا تعديل." /></div></CardContent></Card></section>; }
function RolePolicy({ role, detail }: { role: string; detail: string }) { return <div className="rounded-xl border border-white/8 bg-white/[.02] p-3"><p className="font-bold text-white">{role}</p><p className="mt-1 text-xs leading-6 text-slate-500">{detail}</p></div>; }

function FinanceCenter({ data, rows, plans, pending, onUpdate, onRenew }: any) { const collections = data?.collectionsByGenerator ?? []; return <section className="space-y-6"><div className="grid gap-4 md:grid-cols-4"><Metric label="إيراد الفواتير" value={data?.issuedAmount} icon={CircleDollarSign} /><Metric label="الدفعات المكتملة" value={data?.completedAmount} icon={CheckCircle2} /><Metric label="فواتير متأخرة" value={data?.overdueCount} icon={CalendarClock} /><Metric label="رصيد متأخر" value={data?.overdueAmount} icon={ShieldAlert} /></div><div className="grid gap-6 xl:grid-cols-[.85fr_1.15fr]"><Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><h2 className="font-bold text-white">طرق الدفع الإلكتروني</h2><p className="mt-1 text-sm text-slate-500">إجمالي الدفعات المكتملة المسجلة من مستأجري المنصة.</p><div className="mt-5 space-y-3">{(data?.paymentMethods ?? []).map((row: any) => <div className="flex items-center justify-between rounded-xl border border-white/8 bg-white/[.02] p-3" key={row.method}><span className="text-slate-300">{paymentMethodLabels[String(row.method)] ?? row.method}</span><span className="font-bold text-[#F5B800]">{formatNumber(row.amount)} · {formatNumber(row.count)} دفعة</span></div>)}{!(data?.paymentMethods ?? []).length && <p className="py-6 text-center text-sm text-slate-500">لا توجد دفعات مسجلة بعد.</p>}</div></CardContent></Card><Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><h2 className="font-bold text-white">تقارير التحصيل حسب المولد</h2><p className="mt-1 text-sm leading-7 text-slate-500">الدفعات المكتملة المربوطة بعدادات مولدات المنصة.</p><div className="mt-4 max-h-72 overflow-auto"><table className="w-full min-w-[520px] text-right text-sm"><thead className="text-xs text-slate-500"><tr><th className="pb-3">المولد</th><th className="pb-3">المساحة</th><th className="pb-3">الدفعات</th><th className="pb-3">الإجمالي</th></tr></thead><tbody>{collections.map((row: any) => <tr className="border-t border-white/7" key={row.generatorId}><td className="py-3 text-white">{row.generatorName}<span className="mr-2 text-xs text-slate-500">{row.generatorCode}</span></td><td className="py-3 text-slate-400">{row.tenantName}</td><td className="py-3 text-slate-300">{formatNumber(row.count)}</td><td className="py-3 font-bold text-[#F5B800]">{formatNumber(row.amount)}</td></tr>)}{!collections.length && <tr><td colSpan={4} className="py-8 text-center text-slate-500">لا توجد دفعات مكتملة مرتبطة بمولدات بعد.</td></tr>}</tbody></table></div></CardContent></Card></div><div><h2 className="mb-3 text-lg font-extrabold text-white">الاشتراكات والتجديد</h2><SubscriptionsTab rows={rows} pending={pending} onUpdate={onUpdate} onRenew={onRenew} smsPlans={plans ?? []} /></div></section>; }

function NotificationsCenter({ data, rows }: any) { return <section className="space-y-6"><div className="grid gap-6 xl:grid-cols-[.8fr_1.2fr]"><Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><h2 className="font-bold text-white">تنبيهات النظام</h2><p className="mt-1 text-sm text-slate-500">ملخص رسائل WhatsApp وSMS في طوابير المستأجرين.</p><div className="mt-5 space-y-3">{(data?.statuses ?? []).map((item: any) => <div key={item.status} className="flex items-center justify-between rounded-xl border border-white/8 bg-white/[.02] p-3"><span className="text-slate-300">{notificationStatusLabels[String(item.status)] ?? item.status}</span><span className="font-bold text-[#F5B800]">{formatNumber(item.count)}</span></div>)}{!(data?.statuses ?? []).length && <p className="py-8 text-center text-sm text-slate-500">لا توجد رسائل في السجل بعد.</p>}</div></CardContent></Card><Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><h2 className="font-bold text-white">إرسال إشعار جماعي</h2><p className="mt-2 text-sm leading-7 text-slate-400">إرسال الجماعي إلى قنوات WhatsApp أو SMS معطل في النسخة المحلية حتى يفعّل آدمن المنصة مزوداً خارجياً ويحدد سياسة موافقة لكل مستأجر.</p><textarea disabled placeholder="نص الإشعار الجماعي سيظهر هنا بعد تفعيل القنوات." className="mt-5 min-h-28 w-full rounded-xl border border-white/10 bg-white/[.02] p-3 text-sm text-slate-500" /><Button disabled className="mt-3 w-full bg-white/10 text-slate-500">الإرسال الجماعي مؤجل</Button><div className="mt-4 rounded-xl border border-dashed border-[#F5B800]/25 bg-[#F5B800]/5 p-3 text-xs leading-6 text-slate-400">لا ينفذ مركز الآدمن أي إرسال خارجي من هذه الواجهة قبل تفعيل القنوات والموافقات.</div></CardContent></Card></div><Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><h2 className="font-bold text-white">سجل الإشعارات</h2><div className="mt-4 overflow-x-auto"><table className="w-full min-w-[760px] text-right text-sm"><thead className="text-xs text-slate-500"><tr><th className="pb-3">المستأجر</th><th className="pb-3">القناة / الحدث</th><th className="pb-3">المستلم</th><th className="pb-3">الحالة</th><th className="pb-3">المحاولات</th><th className="pb-3">التاريخ</th></tr></thead><tbody>{rows.map((row: any) => <tr className="border-t border-white/7" key={row.id}><td className="py-3 text-white">{row.tenantName}</td><td className="py-3 text-slate-400">{row.channel} · {row.eventType}</td><td className="py-3 text-slate-400" dir="ltr">{row.recipient}</td><td className="py-3"><Badge className="bg-white/5 text-slate-300">{notificationStatusLabels[row.status] ?? row.status}</Badge></td><td className="py-3 text-slate-400">{formatNumber(row.attempts)}</td><td className="py-3 text-slate-400">{formatDate(row.createdAt)}</td></tr>)}{!rows.length && <tr><td colSpan={6} className="py-8 text-center text-slate-500">لا توجد إشعارات مسجلة حتى الآن.</td></tr>}</tbody></table></div></CardContent></Card></section>; }

function SecurityCenter({ data, security }: any) {
  const events = security?.events ?? [];
  const settings = security?.settings ?? [];
  return <section className="space-y-6"><div className="grid gap-6 xl:grid-cols-2"><Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><h2 className="font-bold text-white">سجل النشاطات</h2><p className="mt-1 text-sm text-slate-500">آخر نشاطات المراجعة المسجلة في مساحات المستأجرين.</p><div className="mt-5 max-h-96 space-y-3 overflow-auto">{(data?.recentAudit ?? []).map((row: any) => <div className="rounded-xl border border-white/8 bg-white/[.02] p-3" key={row.id}><div className="flex items-center justify-between gap-3"><p className="font-bold text-white">{row.action}</p><span className="text-xs text-slate-500">{formatDate(row.createdAt)}</span></div><p className="mt-1 text-xs text-slate-500">{row.tenantName ?? "—"} · {row.siteName ?? "—"} · {row.userName ?? "نظام"}</p></div>)}{!(data?.recentAudit ?? []).length && <p className="py-8 text-center text-sm text-slate-500">لا توجد سجلات تدقيق بعد.</p>}</div></CardContent></Card><Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><h2 className="font-bold text-white">أحداث الأمان والنسخ الاحتياطي</h2><p className="mt-1 text-sm text-slate-500">عرض مركزي للأحداث المسجلة من المسارات التشغيلية.</p><div className="mt-5 max-h-96 space-y-3 overflow-auto">{events.map((event: any) => <div className="rounded-xl border border-white/8 bg-white/[.02] p-3" key={event.id}><div className="flex items-center justify-between gap-3"><p className="font-bold text-white">{event.title}</p><Badge className={event.severity === "critical" ? "bg-rose-400/10 text-rose-300" : "bg-white/5 text-slate-300"}>{event.eventType}</Badge></div><p className="mt-1 text-xs text-slate-500">{event.details ?? "لا توجد تفاصيل"} · {formatDate(event.createdAt)}</p></div>)}{!events.length && <p className="py-8 text-center text-sm text-slate-500">لا توجد أحداث أمان مسجلة بعد.</p>}</div></CardContent></Card></div><Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><h2 className="font-bold text-white">إعدادات الأمان</h2><p className="mt-1 text-sm leading-7 text-slate-500">يتم عرض الإعدادات المركزية فقط؛ لا يوجد في هذه الشاشة إجراء كتابة غير مدعوم.</p><div className="mt-4 space-y-3">{settings.map((setting: any) => <div key={setting.id} className="flex items-center justify-between rounded-xl border border-white/8 bg-white/[.02] p-3 text-sm text-slate-300"><span>{setting.settingKey}</span><Badge className={setting.isEnabled ? "bg-emerald-400/10 text-emerald-300" : "bg-slate-400/10 text-slate-400"}>{setting.isEnabled ? "مفعّل" : "متوقف"}</Badge></div>)}{!settings.length && <p className="py-6 text-center text-sm text-slate-500">لا توجد إعدادات أمان مركزية معروضة.</p>}</div></CardContent></Card></section>;
}

function SecurityCard({ title, text }: { title: string; text: string }) { return <Card className="border-white/8 bg-[#111823]"><CardContent className="p-5"><ShieldAlert className="h-5 w-5 text-[#F5B800]" /><h2 className="mt-4 font-bold text-white">{title}</h2><p className="mt-2 text-sm leading-7 text-slate-500">{text}</p></CardContent></Card>; }
function SettingsCenter({ security, pending, onSaveSetting }: any) { const settings = security?.settings ?? []; return <section className="grid gap-6 md:grid-cols-3"><SecurityCard title="الإعدادات العامة" text="اسم المنتج والهوية واللغات مُدارة من إعدادات المشروع. تُحفظ إعدادات كل مالك مولد داخل مساحته المعزولة." /><SecurityCard title="التكاملات" text="بوابات الدفع الإلكتروني وWhatsApp وSMS في حالة إعداد مؤجل. لا يوجد مزود متصل أو إرسال حي حتى طلب التفعيل الصريح." /><Card className="border-white/8 bg-[#111823]"><CardContent className="p-5"><h2 className="font-bold text-white">إعدادات الحماية</h2><p className="mt-2 text-sm leading-7 text-slate-500">مفاتيح حراسة المنصة المسجلة مركزياً.</p><div className="mt-4 space-y-3">{settings.map((setting: any) => <label className="flex items-center justify-between gap-3 rounded-xl border border-white/8 bg-white/[.02] p-3 text-sm text-slate-300" key={setting.id}>{setting.settingKey}<input type="checkbox" defaultChecked={setting.isEnabled} onChange={(event) => onSaveSetting({ settingKey: setting.settingKey, isEnabled: event.target.checked, value: setting.value ?? undefined })} disabled={pending} className="accent-[#F5B800]" /></label>)}{!settings.length && <Button disabled={pending} onClick={() => onSaveSetting({ settingKey: "platform_audit_guard", isEnabled: true })} className="w-full bg-[#F5B800] text-[#0D1117] hover:bg-[#ffd23f]">تهيئة حراسة التدقيق</Button>}</div></CardContent></Card></section>; }
